<?php
declare(strict_types=1);
require_once __DIR__.'/config/communications_step21.php';
$error=null;$msg=null;$rows=[];$user=[];
try{$pdo=business_db();comm_step21_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=comm_step21_context($pdo);$orgId=(int)$ctx['organization_id'];comm_step21_sync_events($pdo,$orgId);if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');if($id>0)comm_step21_mark_notification($pdo,$orgId,(int)$user['id'],$id,$action);elseif($action==='read_all')$pdo->prepare("UPDATE communication_notifications SET status='read',read_at=COALESCE(read_at,NOW()) WHERE organization_id=? AND user_id=? AND status='unread'")->execute([$orgId,(int)$user['id']]);$msg='Notification state updated.';}$s=$pdo->prepare("SELECT n.*,e.event_status,e.event_type,e.severity FROM communication_notifications n LEFT JOIN communication_events e ON e.id=n.event_id WHERE n.organization_id=? AND n.user_id=? ORDER BY n.created_at DESC LIMIT 150");$s->execute([$orgId,(int)$user['id']]);$rows=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>My Notifications - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>My In-App Notifications</small></span></a><div class="os-top-actions"><a class="os-btn" href="notification_preferences.php">Preferences</a><a class="os-btn primary" href="index.php">Dashboard</a></div></div></header><main class="os-main" style="max-width:1180px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">STEP 21 • NOTIFICATION INBOX</div><h1>Your role-aware Business OS alerts.</h1><p>Only notifications allowed by your permissions are delivered here. When a source condition resolves, its event is closed automatically.</p></section><?php if($error):?><div class="pp-alert bad"><?=comm_step21_h($error)?></div><?php endif;?><?php if($msg):?><div class="pp-alert good"><?=comm_step21_h($msg)?></div><?php endif;?><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Notifications</h2><p><?=count($rows)?> recent item(s)</p></div><form method="post"><input type="hidden" name="action" value="read_all"><button class="os-btn">Mark all read</button></form></div><div class="os-links"><?php if(!$rows):?><div class="pp-empty">No notifications yet.</div><?php endif;?><?php foreach($rows as $r):?><div class="os-link" style="align-items:flex-start"><div><b><?=comm_step21_h($r['title'])?></b><span><?=comm_step21_h($r['body'])?></span><small><?=comm_step21_h((string)$r['created_at'])?> • <?=comm_step21_h(strtoupper((string)$r['priority']))?> • <?=comm_step21_h(strtoupper((string)($r['event_status']??'manual')))?></small></div><div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end"><?php if(!empty($r['action_url'])):?><a class="os-btn" href="<?=comm_step21_h($r['action_url'])?>">Open</a><?php endif;?><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="<?=$r['status']==='unread'?'read':'unread'?>"><button class="os-btn"><?=$r['status']==='unread'?'Read':'Unread'?></button></form><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="dismiss"><button class="os-btn">Dismiss</button></form></div></div><?php endforeach;?></div></section></main></body></html>